namespace sv_97d39ff3f9e84df09a38290a34b9a801.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

using sv_97d39ff3f9e84df09a38290a34b9a801.Models;

namespace sv_97d39ff3f9e84df09a38290a34b9a801.Services;

public class ApplicationService : IApplicationService
{
    private static int _nextId = 1000;

    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1500); // Simulate network call
        return Interlocked.Increment(ref _nextId);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(500); // Simulate network call
        return !string.IsNullOrWhiteSpace(email)
            && email.Contains('@')
            && email.Contains('.');
    }
}

@namespace sv_97d39ff3f9e84df09a38290a34b9a801.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => HandleStepClick(stepIndex)">
                <span class="step-circle">
                    @if (status == "completed")
                    {
                        <span class="step-check">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public int CompletedUpTo { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepStatus(int index)
    {
        if (index == CurrentStep) return "active";
        if (index < CompletedUpTo) return "completed";
        return "dimmed";
    }

    private async Task HandleStepClick(int index)
    {
        if (index < CompletedUpTo)
        {
            await OnStepClicked.InvokeAsync(index);
        }
    }
}

@namespace sv_97d39ff3f9e84df09a38290a34b9a801.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-sm btn-danger" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" class="form-control" value="@Company"
                   @oninput="e => UpdateField(nameof(Company), e.Value?.ToString())" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" class="form-control" value="@Title"
                   @oninput="e => UpdateField(nameof(Title), e.Value?.ToString())" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@StartDateStr"
                   @onchange="e => UpdateStartDate(e.Value?.ToString())" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@EndDateStr" disabled="@IsCurrent"
                   @onchange="e => UpdateEndDate(e.Value?.ToString())" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="e => UpdateIsCurrent((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Description"
                  @oninput="e => UpdateField(nameof(Description), e.Value?.ToString())"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter, EditorRequired] public string Company { get; set; } = "";
    [Parameter, EditorRequired] public string Title { get; set; } = "";
    [Parameter, EditorRequired] public DateTime? StartDate { get; set; }
    [Parameter, EditorRequired] public DateTime? EndDate { get; set; }
    [Parameter, EditorRequired] public bool IsCurrent { get; set; }
    [Parameter, EditorRequired] public string Description { get; set; } = "";
    [Parameter, EditorRequired] public bool CanRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback OnRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<(int Index, string Field, object? Value)> OnFieldChanged { get; set; }

    private string StartDateStr => StartDate?.ToString("yyyy-MM-dd") ?? "";
    private string EndDateStr => EndDate?.ToString("yyyy-MM-dd") ?? "";

    private async Task UpdateField(string field, string? value)
    {
        await OnFieldChanged.InvokeAsync((Index, field, value));
    }

    private async Task UpdateStartDate(string? value)
    {
        DateTime? date = DateTime.TryParse(value, out var d) ? d : null;
        await OnFieldChanged.InvokeAsync((Index, nameof(StartDate), date));
    }

    private async Task UpdateEndDate(string? value)
    {
        DateTime? date = DateTime.TryParse(value, out var d) ? d : null;
        await OnFieldChanged.InvokeAsync((Index, nameof(EndDate), date));
    }

    private async Task UpdateIsCurrent(bool value)
    {
        await OnFieldChanged.InvokeAsync((Index, nameof(IsCurrent), value));
    }
}

