@namespace sv_97d39ff3f9e84df09a38290a34b9a801.Components.Pages.Apply

<div class="step-content">
    <h3>Personal Information</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" class="form-control" value="@FullName"
               @oninput="e => FullName = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" class="form-control" value="@Email"
               @oninput="e => Email = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" class="form-control" value="@Phone"
               @oninput="e => Phone = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea class="form-control" rows="2" value="@Address"
                  @oninput="e => Address = e.Value?.ToString() ?? string.Empty"></textarea>
    </div>

    <div class="step-buttons">
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<(string FullName, string Email, string Phone, string Address)> OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var isValidEmail = await ValidateEmail(Email);
            if (!isValidEmail)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }

            await OnNext.InvokeAsync((FullName, Email, Phone, Address));
        }
        finally
        {
            IsValidating = false;
        }
    }
}

@namespace sv_97d39ff3f9e84df09a38290a34b9a801.Components.Pages.Apply

<div class="step-content">
    <h3>Work History</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var entry = Entries[i];
        <WorkEntryForm Index="i"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       IsCurrent="@entry.IsCurrent"
                       Description="@entry.Description"
                       CanRemove="@(Entries.Count > 1)"
                       OnRemove="() => RemoveEntry(entry)"
                       OnFieldChanged="HandleFieldChanged" />
    }

    <button type="button" class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryModel>> OnNext { get; set; }

    private string? ErrorMessage;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(WorkEntryModel entry)
    {
        if (Entries.Count > 1)
        {
            Entries.Remove(entry);
        }
    }

    private void HandleFieldChanged((int Index, string Field, object? Value) args)
    {
        var entry = Entries[args.Index];
        switch (args.Field)
        {
            case "Company": entry.Company = args.Value?.ToString() ?? ""; break;
            case "Title": entry.Title = args.Value?.ToString() ?? ""; break;
            case "StartDate": entry.StartDate = args.Value as DateTime?; break;
            case "EndDate": entry.EndDate = args.Value as DateTime?; break;
            case "IsCurrent":
                entry.IsCurrent = args.Value is true;
                if (entry.IsCurrent) entry.EndDate = null;
                break;
            case "Description": entry.Description = args.Value?.ToString() ?? ""; break;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == null)
            {
                ErrorMessage = "Each position requires at least a company name, job title, and start date.";
                return;
            }
        }
        await OnNext.InvokeAsync(Entries);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_97d39ff3f9e84df09a38290a34b9a801.Components.Pages.Apply

<div class="step-content">
    <h3>References</h3>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var refEntry = References[i];
        <ReferenceForm Index="i"
                       Name="@refEntry.Name"
                       Relationship="@refEntry.Relationship"
                       Email="@refEntry.Email"
                       Phone="@refEntry.Phone"
                       CanRemove="@(References.Count > 2)"
                       OnRemove="() => RemoveReference(refEntry)"
                       OnFieldChanged="HandleFieldChanged" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnNext { get; set; }

    private string? ErrorMessage;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(ReferenceModel entry)
    {
        if (References.Count > 2)
        {
            References.Remove(entry);
        }
    }

    private void HandleFieldChanged((int Index, string Field, string? Value) args)
    {
        var entry = References[args.Index];
        switch (args.Field)
        {
            case "Name": entry.Name = args.Value ?? ""; break;
            case "Relationship": entry.Relationship = args.Value ?? ""; break;
            case "Email": entry.Email = args.Value ?? ""; break;
            case "Phone": entry.Phone = args.Value ?? ""; break;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "All fields are required for each reference.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_97d39ff3f9e84df09a38290a34b9a801.Components.Pages.Apply

<div class="step-content">
    <h3>Cover Letter</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Write your cover letter below:</label>
        <textarea class="form-control cover-letter-textarea" rows="12" maxlength="2000"
                  value="@CoverLetter"
                  @oninput="e => CoverLetter = e.Value?.ToString() ?? string.Empty"></textarea>
        <span class="char-count">@(CoverLetter?.Length ?? 0) / 2000 characters</span>
    </div>

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }

    private string? ErrorMessage;

    private async Task HandleNext()
    {
        ErrorMessage = null;
        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "Please write a cover letter.";
            return;
        }
        await OnNext.InvokeAsync(CoverLetter);
    }
}

@namespace sv_97d39ff3f9e84df09a38290a34b9a801.Components.Pages.Apply

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <h4>&#10003; Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will be in touch soon.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <section class="review-section">
            <div class="review-section-header">
                <h4>Personal Information</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@FullName</dd>
                <dt>Email</dt><dd>@Email</dd>
                <dt>Phone</dt><dd>@Phone</dd>
                <dt>Address</dt><dd>@Address</dd>
            </dl>
        </section>

        <section class="review-section">
