+    <div class="form-group">
+        <label>Full Name *</label>
+        <input type="text" class="form-control" value="@FullName"
+               @oninput="e => FullName = e.Value?.ToString() ?? string.Empty" />
+    </div>
+
+    <div class="form-group">
+        <label>Email *</label>
+        <input type="email" class="form-control" value="@Email"
+               @oninput="e => Email = e.Value?.ToString() ?? string.Empty" />
+    </div>
+
+    <div class="form-group">
+        <label>Phone *</label>
+        <input type="tel" class="form-control" value="@Phone"
+               @oninput="e => Phone = e.Value?.ToString() ?? string.Empty" />
+    </div>
+
+    <div class="form-group">
+        <label>Address *</label>
+        <textarea class="form-control" rows="2" value="@Address"
+                  @oninput="e => Address = e.Value?.ToString() ?? string.Empty"></textarea>
+    </div>
+
+    <div class="step-buttons">
+        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
+            @(IsValidating ? "Validating..." : "Next")
+        </button>
+    </div>
+</div>
+
+@code {
+    [Parameter] public string FullName { get; set; } = "";
+    [Parameter] public string Email { get; set; } = "";
+    [Parameter] public string Phone { get; set; } = "";
+    [Parameter] public string Address { get; set; } = "";
+    [Parameter, EditorRequired] public EventCallback<(string FullName, string Email, string Phone, string Address)> OnNext { get; set; }
+    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;
+
+    private string? ErrorMessage;
+    private bool IsValidating;
+
+    private async Task HandleNext()
+    {
+        ErrorMessage = null;
+
+        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
+            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
+        {
+            ErrorMessage = "All fields are required.";
+            return;
+        }
+
+        IsValidating = true;
+        try
+        {
+            var isValidEmail = await ValidateEmail(Email);
+            if (!isValidEmail)
+            {
+                ErrorMessage = "Please enter a valid email address.";
+                return;
+            }
+
+            await OnNext.InvokeAsync((FullName, Email, Phone, Address));
+        }
+        finally
+        {
+            IsValidating = false;
+        }
+    }
+}
+

