@namespace sv_97d39ff3f9e84df09a38290a34b9a801.Components.Pages.Apply

<div class="step-content">
    <h3>References</h3>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var refEntry = References[i];
        <ReferenceForm Index="i"
                       Name="@refEntry.Name"
                       Relationship="@refEntry.Relationship"
                       Email="@refEntry.Email"
                       Phone="@refEntry.Phone"
                       CanRemove="@(References.Count > 2)"
                       OnRemove="() => RemoveReference(refEntry)"
                       OnFieldChanged="HandleFieldChanged" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnNext { get; set; }

    private string? ErrorMessage;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(ReferenceModel entry)
    {
        if (References.Count > 2)
        {
            References.Remove(entry);
        }
    }

    private void HandleFieldChanged((int Index, string Field, string? Value) args)
    {
        var entry = References[args.Index];
        switch (args.Field)
        {
            case "Name": entry.Name = args.Value ?? ""; break;
            case "Relationship": entry.Relationship = args.Value ?? ""; break;
            case "Email": entry.Email = args.Value ?? ""; break;
            case "Phone": entry.Phone = args.Value ?? ""; break;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "All fields are required for each reference.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

