@page "/apply"
@namespace sv_97d39ff3f9e84df09a38290a34b9a801.Components.Pages.Apply
@rendermode InteractiveServer
@using sv_97d39ff3f9e84df09a38290a34b9a801.Models

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@_currentStep" CompletedUpTo="@_completedUpTo" OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="@_workEntries" OnBack="() => GoToStep(0)" OnNext="HandleWorkNext" />
            break;
        case 2:
            <ReferencesStep References="@_references" OnBack="() => GoToStep(1)" OnNext="HandleReferencesNext" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter" OnBack="() => GoToStep(2)" OnNext="HandleCoverLetterNext" />
            break;
        case 4:
            <ReviewStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                        WorkEntries="@_workEntries" References="@_references" CoverLetter="@_coverLetter"
                        OnBack="() => GoToStep(3)" OnEditSection="GoToStep" OnSubmit="HandleSubmit"
                        IsSubmitting="@_isSubmitting" IsSubmitted="@_isSubmitted"
                        ApplicationId="@_applicationId" ErrorMessage="@_submitError" />
            break;
    }
</div>

@code {
    private int _currentStep = 0;
    private int _completedUpTo = 0;

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 state
    private List<WorkHistoryStep.WorkEntryModel> _workEntries = new() { new() };

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> _references = new() { new(), new() };

    // Step 4 state
    private string _coverLetter = "";

    // Submission state
    private bool _isSubmitting;
    private bool _isSubmitted;
    private int _applicationId;
    private string? _submitError;

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private void HandlePersonalNext((string FullName, string Email, string Phone, string Address) data)
    {
        _fullName = data.FullName;
        _email = data.Email;
        _phone = data.Phone;
        _address = data.Address;
        AdvanceTo(1);
    }

    private void HandleWorkNext(List<WorkHistoryStep.WorkEntryModel> entries)
    {
        _workEntries = entries;
        AdvanceTo(2);
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        _references = refs;
        AdvanceTo(3);
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        AdvanceTo(4);
    }

    private void AdvanceTo(int step)
    {
        _currentStep = step;
        if (step > _completedUpTo)
            _completedUpTo = step;
    }

    private async Task HandleSubmit()
    {
        _isSubmitting = true;
        _submitError = null;

        try
        {
            var workEntries = _workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate!.Value, e.EndDate, e.Description)).ToList();

            var references = _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(
                new PersonalInfo(_fullName, _email, _phone, _address),
                new WorkHistory(workEntries),
                references,
                _coverLetter);

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _isSubmitted = true;
        }
        catch (Exception ex)
        {
            _submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

